import{_ as a,o as i,c as n,ag as o}from"./chunks/framework.PVHj0As1.js";const r="/pub-blog/assets/image-20241219092436235.DDqaOWQt.png",l="/pub-blog/assets/image-20241219093119586.qpjjoMHn.png",t="/pub-blog/assets/image-20241219093722816.LVwtuSp6.png",u="/pub-blog/assets/image-20241219093840013.CLVlEV9X.png",d="/pub-blog/assets/image-20241219093925639.DHiCoUFx.png",p="/pub-blog/assets/image-20241219094156393.CUDDsdoW.png",s="/pub-blog/assets/image-20241219094225699.oYLvUu9e.png",c="/pub-blog/assets/image-20241219094414865.CPABkZmF.png",f=JSON.parse('{"title":"uniapp极速上手鸿蒙开发","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/uniapp极速上手鸿蒙开发/uniapp极速上手鸿蒙开发.md","filePath":"鸿蒙开发技巧/uniapp极速上手鸿蒙开发/uniapp极速上手鸿蒙开发.md","lastUpdated":1734572792000,"__rawMarkdown":"# uniapp极速上手鸿蒙开发\\n\\nuniapp 团队 与版本 `4.28.2024092502`  起，支持鸿蒙应用开发，现在是  `4.36.2024112817`,同时支持鸿蒙应用和元服务开发了。\\n\\n我们现在上手感受一下\\n\\n## 环境配置\\n\\n- HBuilderX 4.24+ [下载地址](https://www.dcloud.io/hbuilderx.html)\\n- [DevEco Studio](https://developer.huawei.com/consumer/cn/download/)\\n  - HBuilderX 4.24+ 要求 DevEco-Studio 5.0.3.400+，HBuilderX 4.31+ 要求 DevEco-Studio 5.0.3.800+。\\n  - 鸿蒙系统版本 API 12 以上 （DevEco-Studio有内置鸿蒙模拟器）\\n- **HBuilderX 4.31+ 构建的鸿蒙运行包不支持 x86_64 平台，会影响到 Windows 系统和部分 Mac 系统的鸿蒙模拟器无法使用，需使用真机调试**\\n\\n**底下主要针对真机做的演示**\\n\\n## 项目要求\\n\\n在创建uniapp项目的时候，需要选择 vue3，vue2不支持\\n\\n\\n\\n## 搭建流程\\n\\n1. AGC平台上新建项目，目的是活动boundleName以及调试和发布证书\\n2. 下载和安装 DevEco Studio\\n3. 使用 **DevEco Studio** 创建项目，然后配置boundleName和调试和发布证书\\n4. 复制证书相关的配置\\n5. 下载和安装 hbuilder\\n6. hbuilder 下载相关插件\\n7. hbuilder 配置  DevEco Studio 工具路径\\n8. hbuilder新建uniapp vue3工程\\n9. hbuilder配置鸿蒙应用的证书\\n10. hbuilder运行项目\\n\\n\\n\\n## AGC平台上新建项目\\n\\n可以根据需求选择新建工程还是[项目](https://developer.huawei.com/consumer/cn/doc/app/agc-help-createproject-0000001100334664)。  这里选择项目\\n\\n\\n\\n## 下载和安装 DevEco Studio\\n\\n下载和安装[DevEco Studio](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/ide-software-install-V5)\\n\\n\\n\\n## boundleName和调试和发布证书\\n\\n因为真机在调试时候需要使用调试证书\\n\\n应用在发布的时候需要使用发布整数，因此一次性都配置获得即可\\n\\n[配置链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/application-dev-overview-V5#section42841246144813)\\n\\n![image-20241219092436235](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219092436235.png)\\n\\n## DevEco Studio 新建项目获得证书配置信息\\n\\n这个步骤主要为了得到证书的配置代码，uniapp运行项目的时候需要用到\\n\\n在使用DevEco Studio新建完项目后，参考链接 [进行证书的配置](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/ide-signing-V5#section297715173233)\\n\\n得到配置文件 `build-profile.json5`   后续复制整个代码到uniapp创建的项目即可\\n\\n![image-20241219093119586](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219093119586.png)\\n\\n## 下载和安装 hbuilder\\n\\n[这里下载和安装](https://www.dcloud.io/hbuilderx.html)\\n\\n\\n\\n## hbuilder 下载相关插件\\n\\n`工具-插件安装`   关键是这几个 `鸿蒙、vue3`\\n\\n![image-20241219093722816](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219093722816.png)\\n\\n\\n\\n## hbuilder 配置  DevEco Studio 工具路径\\n\\n这里配置DevEco Studio 工具的路径  `工具-设置`\\n\\n![image-20241219093840013](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219093840013.png)\\n\\n\\n\\n## hbuilder新建uniapp vue3工程\\n\\n新建vue3工程\\n\\n![image-20241219093925639](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219093925639.png)\\n\\n##  hbuilder配置鸿蒙应用的证书\\n\\n在项目根目录下配置 `\\\\harmony-configs\\\\build-profile.json5`    如果不存在，则手动新建。\\n\\n然后复制、粘贴证书代码进去\\n\\n![image-20241219094156393](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219094156393.png)\\n\\n\\n\\n##  hbuilder运行项目\\n\\n最后，运行项目\\n\\n![image-20241219094225699](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219094225699.png)\\n\\n## 效果\\n\\n![image-20241219094414865](uniapp%E6%9E%81%E9%80%9F%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91.assets/image-20241219094414865.png)"}'),h={name:"鸿蒙开发技巧/uniapp极速上手鸿蒙开发/uniapp极速上手鸿蒙开发.md"};function m(b,e,E,g,v,_){return i(),n("div",null,[...e[0]||(e[0]=[o("",44)])])}const D=a(h,[["render",m]]);export{f as __pageData,D as default};
